def cc(n):
    s = ''
    while n != 0:
        s = str(n % 5) + s
        n //= 5
    return s

def f(n):
    s = cc(n)
    if len(s) % 2 == 0:
        s = s[len(s) // 2:] + s[:len(s) // 2]
    else:
        s = s + str(n % 5)
        s = s[len(s) // 2:] + s[:len(s) // 2]
    return int(s,5)

for i in range(1,1000):
    if f(i)>50:
        print(i)
        break
